  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated administrator account's {@link econ_politic_board_admins.id.
  admin_id String @db.Uuid

  /// Secure one-time token for password reset requests. Generated as random
  /// UUID with SHA-256 hashing for security.
  reset_token String

  /// Token expiration datetime. Set to 1 hour from creation for security.
  expires_at DateTime @db.Timestamptz

  /// Token creation timestamp for audit purposes.
  created_at DateTime @db.Timestamptz

  /// Soft delete timestamp for record retention policies.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  admin econ_politic_board_admins @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@unique([reset_token])
  // spellchecker: ignore-next-line
  @@index([admin_id, expires_at], map: "econ_politic_board_admin_password_resets_admin_id_expi_bc300606")
}

