/// @author AutoBE - https://github.com/wrtnlabs/autobe
model econ_politic_board_article_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Article attachment belongs to article's {@link
  /// econ_politic_board_articles.id}.
  econ_politic_board_article_id String @db.Uuid

  /// Original file name of the attachment, including extension.
  file_name String

  /// MIME type of the file (e.g., image/jpeg, application/pdf).
  file_type String

  /// File size in bytes, limited to a total of 50MB per article across all
  /// attachments.
  file_size Int @db.Integer

  /// Where the file is stored (URL or path), typically a cloud storage path.
  storage_location String

  /// Timestamp when the attachment was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the attachment was last modified.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the attachment was soft-deleted, allowing audit while
  /// maintaining article integrity.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  article econ_politic_board_articles @relation(fields: [econ_politic_board_article_id], references: [id], onDelete: Cascade, map: "econ_politic_board_article_attachments_econ_politic_bo_80cf4479")

  // spellchecker: ignore-next-line
  @@index([econ_politic_board_article_id, created_at], map: "econ_politic_board_article_attachments_econ_politic_bo_113987c3")
}

/// Tag values used for categorization and filtering of articles.
///
/// Each article can have up to five tags, with a maximum length of 20
